final class ArtisticGeneratedAdoptionTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $floors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_models','ai_tasks','integrations','integration_secrets','research_candidates','research_reviews','opportunities','product_families','products','product_versions']as $m){$t=DigiForge\Database\Tables::{$m}();$this->floors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->floors,true)as $t=>$id)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$id);$this->restoreFixture();}
 private function checked($v):array {self::assertNotWPError($v,is_wp_error($v)?$v->get_error_code():'');return $v;}
 private function fixture(string $engine):array {
  $h=new FiveEngineArchitectureTest();[$request,$path,$rights]=(new ReflectionMethod($h,'fixture'))->invoke($h,$engine);$request['limits']=array_replace($request['limits'],['max_output_bytes'=>2097152,'max_pixels'=>1048576,'max_execution_seconds'=>20]);$w=new DigiForge\POD\TransformationWorkflow();if($engine==='AI_TRANSFORM')$this->checked($w->registerMode('personalized_pod',(new ReflectionMethod($h,'syntheticMode'))->invoke($h,$rights)));$key=wp_generate_uuid4();$this->checked($w->create('personalized_pod',$key,$request,$path,$rights));$source=$this->checked($w->verifyInput('personalized_pod',$key));unlink($path);$policy=$this->checked((new ReflectionMethod(ImageGenerationExecutionTest::class,'policy'))->invoke(new ImageGenerationExecutionTest()));$spec=ImagePanelFixture::specification();$t=(new ReflectionMethod(ImageGenerationExecutionTest::class,'transport'))->invoke(new ImageGenerationExecutionTest());return [$key,$source,$spec,$policy,new DigiForge\AI\ImageGenerationExecution($t),$t];
 }
 private function prepare(array $f):array {[$key,$src,$spec,$policy,$s]=$f;self::assertTrue(method_exists($s,'prepareTransformationDesign'),'Artistic candidates need an immutable approved-design target before execution.');return $this->checked($s->prepareTransformationDesign('personalized_pod',$key,$src['event_sha256'],$spec['hash'],$policy['hash'],['run_id'=>'artistic-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')],true));}
 private function generate(array $f):array {$j=$this->prepare($f);$this->checked((new DigiForge\AI\MonetaryReservationRepository())->reviewQuote('personalized_pod',ImagePanelFixture::quote($j),'CONFIRM_PROVIDER_QUOTE'));return $this->checked($f[4]->run('personalized_pod',$j['id']));}
 private function payload():array{return ['svg'=>file_get_contents(__DIR__.'/../fixtures/design-factory/mug-original.svg'),'raster_uploads'=>[],'rights_note'=>'SYNTHETIC separately reviewed generated output and editable adaptation; not source-reference licensing','source_note'=>'Synthetic manual adaptation; no vector or print fidelity inferred'];}
 /** @dataProvider engines */
 public function testEachEngineHasBoundEditableReviewAndImmutableRevision(string $engine):void {
  $f=$this->fixture($engine);[$key,$src,$spec,,$s]=$f;$j=$this->generate($f);$linked=$this->checked($s->linkDerivative('personalized_pod',$j['id'],$j['result']['sha256'],$this->payload(),true,$j['event_sha256']));$r=new DigiForge\Research\DesignFactoryRepository();$v=$this->checked($r->read('personalized_pod',$linked['derivative_hash']));$o=$v['record']['provenance']['generated_source'];self::assertSame($engine,$o['artistic_binding']['engine']);self::assertSame($src['request']['product_version_id'],$o['artistic_binding']['product_version_id']);self::assertSame($src['source']['sha256'],$o['artistic_binding']['input_sha256']);self::assertSame($spec['hash'],$o['specification_sha256']);self::assertSame('INPUT_VERIFIED',(new DigiForge\POD\TransformationWorkflow())->read('personalized_pod',$key)['state']);self::assertNotSame($src['rights']['result_asset_sha256'],$o['raster_sha256'],'Original reference manifest must not be rewritten into generated-output rights.');
  self::assertTrue(method_exists($r,'generatedInput'),'Reviewers need the exact source input alongside generated output.');$png=$this->checked($r->generatedInput('personalized_pod',$v['hash']));self::assertSame($src['source']['sha256'],hash('sha256',base64_decode($png['base64'])));$reviewer=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($reviewer);ShopAccessFixture::authorizeActor($reviewer,['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research']);wp_get_current_user()->add_cap('manage_digiforge_ai',false);$approved=$this->checked($r->review('personalized_pod',$v['hash'],'APPROVE',array_fill_keys(DigiForge\Research\DesignFactoryContract::REVIEW_CRITERIA,true),'SYNTHETIC software review only'));self::assertSame($o,$this->checked($r->handoff('personalized_pod',$approved['hash']))['design_metadata']['generated_source']);$rev=$this->checked($r->revise('personalized_pod',$approved['hash'],'New artwork needs new approval'));self::assertNull($rev['review_state']);self::assertWPError($r->handoff('personalized_pod',$rev['hash']));self::assertSame(1,$f[5]->calls());
 }
 public function testTargetDiscoveryAndServerInjectedSimulationPortal():void {
  $f=$this->fixture('WATERCOLOR');[$key,$src,$spec,$policy,$s]=$f;$panel=new DigiForge\Portal\CommercialResearchPanel(null,$s);$p=['operation'=>'design_image_prepare_artistic','shop_key'=>'personalized_pod','workflow_hash'=>$spec['record']['commercial_hash'],'factory_hash'=>$spec['hash'],'transformation_key'=>$key,'policy_hash'=>$policy['hash'],'run_id'=>'panel-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s'),'confirm'=>'1'];$result=$this->checked($panel->process($p));$j=$result['image_job'];self::assertTrue(method_exists(new DigiForge\AI\ImageGenerationJournal(),'forDesign'));$list=$this->checked((new DigiForge\AI\ImageGenerationJournal())->forDesign($spec['hash']));self::assertSame($j['id'],$list[0]['id']);$other=ImagePanelFixture::specification();self::assertSame([],$this->checked((new DigiForge\AI\ImageGenerationJournal())->forDesign($other['hash'])));$this->checked((new DigiForge\AI\MonetaryReservationRepository())->reviewQuote('personalized_pod',ImagePanelFixture::quote($j),'CONFIRM_PROVIDER_QUOTE'));$p['operation']='design_image_run';$p['image_job_id']=$j['id'];self::assertWPError((new DigiForge\Portal\ImageGenerationPanel())->process($p),'POST cannot inject a simulator or enable network dispatch.');$done=$this->checked($panel->process($p));self::assertSame('SUCCEEDED',$done['image_job']['state']);ob_start();(new DigiForge\Portal\ImageGenerationPanel($s))->render('personalized_pod',$spec['record']['commercial_hash'],$spec['hash']);$html=ob_get_clean();self::assertStringContainsString('design_image_prepare_artistic',$html);self::assertStringContainsString('SYNTHETIC OFFLINE',$html);preg_match('/<select name="parent_job">(.*?)<\/select>/s',$html,$parents);self::assertStringNotContainsString($j['id'],$parents[1]??'','Original-artwork successors cannot select artistic parents.');self::assertSame(1,$f[5]->calls());
 }
 public function testModeRegistryMutationDeniesCurrentArtisticSource():void {
  $f=$this->fixture('AI_TRANSFORM');$j=$this->prepare($f);global $wpdb;$name='df_transform_mode_'.hash('sha256','personalized_pod|synthetic-mode|1.0.0');$raw=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name));$changed=json_decode($raw,true);$changed['prompt_revision']='different';$wpdb->update($wpdb->options,['option_value'=>json_encode($changed)],['option_name'=>$name]);try{self::assertWPError((new DigiForge\POD\TransformationWorkflow())->read('personalized_pod',$f[0]));self::assertWPError($f[4]->run('personalized_pod',$j['id']));self::assertSame(0,$f[5]->calls());}finally{$wpdb->update($wpdb->options,['option_value'=>$raw],['option_name'=>$name]);}
 }
 public function testRevocationDuringTargetDiscoveryDeniesPromptBearingRecords():void {
  $f=$this->fixture('PET_PORTRAIT');$j=$this->prepare($f);$revoked=false;$q=static function($sql)use(&$revoked){if(!$revoked&&str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,'image')&&str_contains($sql,'target')){$revoked=true;wp_get_current_user()->add_cap('manage_digiforge_ai',false);}return $sql;};add_filter('query',$q);try{self::assertWPError((new DigiForge\AI\ImageGenerationJournal())->forDesign($f[2]['hash']));self::assertTrue($revoked,'Revocation must occur during target-index discovery, after initial admission.');}finally{remove_filter('query',$q);wp_get_current_user()->add_cap('manage_digiforge_ai',true);}
 }
 public function testCancelledSourceStillAllowsAuthenticatedLocalCleanup():void {
  $f=$this->fixture('PET_PORTRAIT');$j=$this->prepare($f);$this->checked((new DigiForge\POD\TransformationWorkflow())->cancel('personalized_pod',$f[0]));self::assertWPError($f[4]->run('personalized_pod',$j['id']));$p=['operation'=>'design_image_cancel','shop_key'=>'personalized_pod','workflow_hash'=>$f[2]['record']['commercial_hash'],'factory_hash'=>$f[2]['hash'],'image_job_id'=>$j['id'],'confirm'=>'1'];$result=$this->checked((new DigiForge\Portal\ImageGenerationPanel($f[4]))->process($p));self::assertSame('CANCELLED',$result['image_job']['state']);self::assertSame(0,$result['image_job']['usage_id']);self::assertSame(0,$f[5]->calls());
 }
